if (PAYMENTS_MODE === 'LIVE' && isSandboxCredential(KEY)) throw new Error('Sandbox credential cannot run in LIVE');
verifySignature(webhook);
assertIdempotency(eventId);

eligible = filterEligibleRiders(order, riders, rules);
ranked = score(eligible, versionedPolicy);
offer = createSingleOffer(ranked[0], order, versionedPolicy);
